def find_on_shelf(ids, target):
    lo, hi = 0, len(ids) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if ids[mid] == target:
            return mid
        if ids[lo] <= ids[mid]:
            if ids[lo] <= target < ids[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if ids[mid] < target <= ids[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

