class Solution {
    public int findOnShelf(int[] ids, int target) {
        int lo = 0, hi = ids.length - 1;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            if (ids[mid] == target) return mid;
            if (ids[lo] <= ids[mid]) {
                if (ids[lo] <= target && target < ids[mid]) hi = mid - 1;
                else lo = mid + 1;
            } else {
                if (ids[mid] < target && target <= ids[hi]) lo = mid + 1;
                else hi = mid - 1;
            }
        }
        return -1;
    }
}

